const tabId = 2126149158;
const meUrls = [
  { key: "me_rachel", url: "https://moderneternity.com/collections/3-in-1-maternity-coats/products/maternity-coat-rachel-3in1-babywearing-coat" },
  { key: "me_sara", url: "https://moderneternity.com/collections/3-in-1-maternity-coats/products/maternity-parka-sara-3-in-1-down-coat" },
  { key: "me_sofia", url: "https://moderneternity.com/collections/3-in-1-maternity-coats/products/maternity-parka-sofia-3in1-waxed-shell-waterproof-coat" },
  { key: "me_leia", url: "https://moderneternity.com/collections/3-in-1-maternity-coats/products/leia-3in1-quilted-maternity-hybrid-puffer-jacket" }
];

const meResults = [];

for (const item of meUrls) {
  await tool.navigate({ tabId, url: item.url });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
  const data = await browserjs(tabId, () => {
    const title = document.querySelector("h1")?.innerText?.trim();
    const price = document.querySelector(".price, [class*='price-item'], [data-product-price]")?.innerText?.trim();
    const desc = document.querySelector(".product__description, [class*='description']")?.innerText?.trim();

    // sizes
    const sizeEls = Array.from(document.querySelectorAll('input[name*="Size"], input[name*="size"], label[for*="Size"], .swatch-element, [data-value]'));
    const sizes = Array.from(new Set(sizeEls.map(e => e.value || e.getAttribute("data-value") || e.innerText?.trim()))).filter(s => ["XS", "S", "M", "L", "XL", "2XL", "XXL", "1X", "2X", "3X"].includes(s?.toUpperCase()));

    // images
    const images = Array.from(document.querySelectorAll('img[src*="cdn.shopify.com/s/files"]')).map(img => img.src).slice(0, 5);

    return { title, price, desc, sizes, images, url: window.location.href };
  });
  meResults.push(data);
}

console.log("Modern Eternity scraped items:\n", JSON.stringify(meResults, null, 2));

