  { key: "didy_copenhagen", url: "https://www.didymos.de/en/accessories/babywearing-clothes/babywearing-jackets/winter-babywearing-coat-copenhagen.html" },
  { key: "mmbf_universal", url: "https://makemybellyfit.com/products/universal-jacket-extender" },
  { key: "mw_amethyst", url: "https://www.mountainwarehouse.com/p/051899/mw/maternity-amethyst-womens-long-padded-jacket/black/" }
];

const scrapedData = [];

for (const t of targets) {
  await tool.navigate({ tabId, url: t.url });
