  const d = await browserjs(tabId, () => {
    const title = document.querySelector("h1")?.innerText?.trim();
    const price = document.querySelector(".price, [class*='price-item'], [data-product-price], [class*='product--price'], [itemprop='price']")?.innerText?.trim() ||
                  document.querySelector('[class*="price"]')?.innerText?.trim();

    // schema ld+json if available
    const schema = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => {
      try { return JSON.parse(s.innerText); } catch (e) { return null; }
    }).find(j => j && (j.name || j["@type"] === "Product"));

    // description
    const desc = document.querySelector(".product-description, .product__description, [class*='description'], [itemprop='description']")?.innerText?.trim() ||
                 document.body.innerText.slice(0, 2000);

    // sizes
    const sizeEls = Array.from(document.querySelectorAll('input[name*="Size"], input[name*="size"], label[for*="Size"], select[name*="id"] option, .swatch-element, [data-value]'));
    const sizes = Array.from(new Set(sizeEls.map(e => e.value || e.getAttribute("data-value") || e.innerText?.trim()))).filter(s => s && s.length < 20);

    return {
      title,
      price,
      schemaPrice: schema?.offers?.price || schema?.offers?.[0]?.price,
      descSnippet: desc.slice(0, 1500),
      sizes: sizes.slice(0, 10),
      url: window.location.href
    };
  });
  scrapedData.push({ key: t.key, data: d });
}

console.log("Scraped 8-12:", JSON.stringify(scrapedData, null, 2));

